INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('gdpr-art-5-1d', 'GDPR-PR', 'Art.5.1d', 'Accuracy', 'Keep personal data accurate and, where necessary, kept up to date.', TRUE) ON CONFLICT (id) DO NOTHING;
