INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('gdpr-art-7', 'GDPR-LB', 'Art.7', 'Conditions for Consent', 'Where consent is the basis, obtain and record freely given, specific consent.', TRUE) ON CONFLICT (id) DO NOTHING;
