INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('gdpr-art-13-14', 'GDPR-DSR', 'Art.13-14', 'Information to be Provided', 'Provide privacy information at the point of collection.', TRUE) ON CONFLICT (id) DO NOTHING;
