INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('gdpr-art-17', 'GDPR-DSR', 'Art.17', 'Right to Erasure', 'Enable erasure of personal data where grounds apply.', TRUE) ON CONFLICT (id) DO NOTHING;
