INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('gdpr-art-20', 'GDPR-DSR', 'Art.20', 'Data Portability', 'Provide personal data in a structured, machine-readable format.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('gdpr-art-21', 'GDPR-DSR', 'Art.21', 'Right to Object', 'Enable data subjects to object to processing, including profiling.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('gdpr-art-24', 'GDPR-OB', 'Art.24', 'Controller Responsibility', 'Implement appropriate technical and organisational measures to ensure compliance.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('gdpr-art-25', 'GDPR-OB', 'Art.25', 'Data Protection by Design', 'Implement data protection by design and by default.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('gdpr-art-28', 'GDPR-OB', 'Art.28', 'Processor Contracts', 'Use written contracts with processors setting out required obligations.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('gdpr-art-30', 'GDPR-OB', 'Art.30', 'Records of Processing', 'Maintain records of processing activities.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('gdpr-art-32', 'GDPR-SEC', 'Art.32', 'Security of Processing', 'Implement appropriate security measures relative to the risk.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('gdpr-art-33', 'GDPR-SEC', 'Art.33', 'Breach Notification (Authority)', 'Notify the supervisory authority of a breach within 72 hours where required.', TRUE) ON CONFLICT (id) DO NOTHING;
