INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('eu_ai_act-art-14-1', 'EUAI-HO', 'Art.14.1', 'Human Oversight Measures', 'Design the system so it can be effectively overseen by natural persons.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('eu_ai_act-art-14-4', 'EUAI-HO', 'Art.14.4', 'Oversight Capabilities', 'Enable overseers to understand, monitor and intervene or stop the system.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('eu_ai_act-art-15-1', 'EUAI-AR', 'Art.15.1', 'Accuracy', 'Achieve an appropriate level of accuracy and declare metrics.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('eu_ai_act-art-15-4', 'EUAI-AR', 'Art.15.4', 'Robustness', 'Ensure resilience against errors, faults and inconsistencies.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('eu_ai_act-art-15-5', 'EUAI-AR', 'Art.15.5', 'Cybersecurity', 'Ensure resilience against attempts to alter use, behaviour or performance.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('eu_ai_act-art-17-1', 'EUAI-QM', 'Art.17.1', 'Quality Management System', 'Put a quality management system in place for high-risk AI systems.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('eu_ai_act-art-43', 'EUAI-CA', 'Art.43', 'Conformity Assessment', 'Undergo the relevant conformity assessment procedure before market placement.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('eu_ai_act-art-47', 'EUAI-CA', 'Art.47', 'EU Declaration of Conformity', 'Draw up a written EU declaration of conformity.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('eu_ai_act-art-49', 'EUAI-CA', 'Art.49', 'Registration', 'Register the high-risk AI system in the EU database.', TRUE) ON CONFLICT (id) DO NOTHING;
