INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('eu_ai_act-art-73', 'EUAI-PM', 'Art.73', 'Incident Reporting', 'Report serious incidents to the relevant market surveillance authority.', TRUE) ON CONFLICT (id) DO NOTHING;
